mapper.select:
SELECT v.id, v.title, v.cover_url, v.total_duration, v.episode_count, COALESCE((SELECT SUM(e.play_count) FROM public.video_episode e WHERE e.video_id = v.id AND e.is_delete = 0), 0) AS play_count, COALESCE((SELECT SUM(e.favorite_count) FROM public.video_episode e WHERE e.video_id = v.id AND e.is_delete = 0), 0) AS favorite_count, v.is_ongoing, v.video_status, v.create_time, c.name AS category_name, u.nike_name, u.avatar, u.uid, (SELECT CASE WHEN COUNT(*) = 0 THEN 0 WHEN SUM(CASE WHEN e.review_status = 0 THEN 1 ELSE 0 END) = COUNT(*) THEN 0 WHEN SUM(CASE WHEN e.review_status = 0 THEN 1 ELSE 0 END) > 0 THEN 1 ELSE 2 END FROM public.video_episode e WHERE e.video_id = v.id AND e.is_delete = 0) AS review_status FROM public.video_info v LEFT JOIN public.category c ON v.category_id = c.id AND c.is_delete = 0 LEFT JOIN public.user_info u ON v.user_id = u.id
v.is_delete = 0
AND v.title LIKE CONCAT('%', #{title}, '%')
AND v.category_id = #{categoryId}
AND EXISTS ( SELECT 1 FROM public.video_episode e WHERE e.video_id = v.id AND e.is_delete = 0 AND e.review_status = #{reviewStatus} )
AND u.nike_name LIKE CONCAT('%', #{nickName}, '%')
AND v.is_ongoing = #{isOngoing}
AND u.uid LIKE CONCAT('%', #{uid}, '%')
ORDER BY ${orderColumn} ${orderDirection}
ORDER BY v.create_time DESC
